 internal sealed class EditorTextFile {
  internal string Path,Text,Stamp;internal Encoding Encoding;internal byte[] Preamble;internal const int Limit=16*1024*1024;
  internal static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes));}
  internal static EditorTextFile Load(string path){path=System.IO.Path.GetFullPath(path);PathSafety.RejectLinks(path);byte[] bytes;using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){if(input.Length>Limit)throw new IOException(L.Text("codeEditor.large"));bytes=new byte[(int)input.Length];int read=0,n;while(read<bytes.Length&&(n=input.Read(bytes,read,bytes.Length-read))>0)read+=n;if(read!=bytes.Length)throw new EndOfStreamException();}int skip=0;Encoding encoding=new UTF8Encoding(false,true);byte[] bom=new byte[0];if(bytes.Length>=4&&bytes[0]==255&&bytes[1]==254&&bytes[2]==0&&bytes[3]==0){encoding=new UTF32Encoding(false,true,true);skip=4;}else if(bytes.Length>=4&&bytes[0]==0&&bytes[1]==0&&bytes[2]==254&&bytes[3]==255){encoding=new UTF32Encoding(true,true,true);skip=4;}else if(bytes.Length>=3&&bytes[0]==239&&bytes[1]==187&&bytes[2]==191)skip=3;else if(bytes.Length>=2&&bytes[0]==255&&bytes[1]==254){encoding=new UnicodeEncoding(false,true,true);skip=2;}else if(bytes.Length>=2&&bytes[0]==254&&bytes[1]==255){encoding=new UnicodeEncoding(true,true,true);skip=2;}string text;try{text=encoding.GetString(bytes,skip,bytes.Length-skip);}catch(DecoderFallbackException){if(skip!=0)throw;encoding=System.Text.Encoding.GetEncoding(1250,EncoderFallback.ExceptionFallback,DecoderFallback.ExceptionFallback);text=encoding.GetString(bytes);}if(text.IndexOf('\0')>=0)throw new IOException(L.Text("codeEditor.binary"));return new EditorTextFile{Path=path,Text=text,Encoding=encoding,Preamble=bytes.Take(skip).ToArray(),Stamp=Hash(bytes)};}
  static string FileStamp(string path){using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){if(stream.Length>Limit)throw new IOException(L.Text("codeEditor.conflict"));using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(stream));}}
  internal static EditorTextFile New(){return new EditorTextFile{Text="",Encoding=new UTF8Encoding(false,true),Preamble=new byte[0]};}
  internal void Save(string text){if(String.IsNullOrEmpty(Path))throw new IOException(L.Text("codeEditor.saveAs"));PathSafety.RejectLinks(Path);if(text.Length>Limit)throw new IOException(L.Text("codeEditor.large"));byte[] body=Encoding.GetBytes(text);if((long)body.Length+Preamble.Length>Limit)throw new IOException(L.Text("codeEditor.large"));byte[] bytes=Preamble.Concat(body).ToArray();string temp=System.IO.Path.Combine(System.IO.Path.GetDirectoryName(Path),".fc-editor-"+Guid.NewGuid().ToString("N")+".tmp");try{using(PathSafety.LockAncestors(Path)){if(Stamp!=null){if(!File.Exists(Path)||FileStamp(Path)!=Stamp)throw new IOException(L.Text("codeEditor.conflict"));if((File.GetAttributes(Path)&FileAttributes.ReadOnly)!=0)throw new UnauthorizedAccessException(L.Text("ext.readOnly"));}else if(File.Exists(Path))throw new IOException(L.Text("codeEditor.conflict"));using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){output.Write(bytes,0,bytes.Length);output.Flush(true);}if(Stamp!=null){if(FileStamp(Path)!=Stamp)throw new IOException(L.Text("codeEditor.conflict"));File.Replace(temp,Path,null);}else File.Move(temp,Path);Stamp=Hash(bytes);Text=text;}}finally{if(File.Exists(temp))File.Delete(temp);}}
 }
 internal sealed class JsonTextFormatter {
  readonly string input,nl;readonly int spaces;int at;readonly StringBuilder output=new StringBuilder();
  JsonTextFormatter(string text,int indent,string newline){input=text;spaces=indent;nl=newline;}
  internal static string Format(string text,int indent=2,string newline="\r\n"){var parser=new JsonTextFormatter(text,indent,newline);parser.Value(0);parser.White();if(parser.at!=text.Length)parser.Fail();return parser.output.ToString();}
  void Fail(){int line=1,column=1;for(int i=0;i<at&&i<input.Length;i++){if(input[i]=='\n'){line++;column=1;}else column++;}throw new FormatException(L.Format("codeEditor.jsonError",line,column));}
  void White(){while(at<input.Length&&" \t\r\n".IndexOf(input[at])>=0)at++;}
  void Emit(string value){if(output.Length+value.Length>64*1024*1024)throw new FormatException(L.Text("codeEditor.large"));output.Append(value);}
  void Indent(int level){Emit(nl+new string(' ',level*spaces));}
  string String(){White();int start=at;if(at>=input.Length||input[at++]!='"'){Fail();return null;}while(at<input.Length){char c=input[at++];if(c=='"')return input.Substring(start,at-start);if(c<32)Fail();if(c=='\\'){if(at>=input.Length)Fail();char escape=input[at++];if(escape=='u'){for(int i=0;i<4;i++)if(at>=input.Length||!Uri.IsHexDigit(input[at++]))Fail();}else if("\"\\/bfnrt".IndexOf(escape)<0)Fail();}}Fail();return null;}
  void Value(int level){if(level>128)Fail();White();if(at>=input.Length)Fail();char c=input[at];if(c=='{'||c=='['){at++;bool obj=c=='{';char end=obj?'}':']';Emit(c.ToString());White();if(at<input.Length&&input[at]==end){at++;Emit(end.ToString());return;}var keys=new HashSet<string>(StringComparer.Ordinal);while(true){Indent(level+1);if(obj){string key=String();string decoded=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<string>(key);if(!keys.Add(decoded))throw new FormatException(L.Text("codeEditor.duplicateKey"));Emit(key);White();if(at>=input.Length||input[at++]!=':')Fail();Emit(": ");}Value(level+1);White();if(at>=input.Length)Fail();if(input[at]==end){at++;Indent(level);Emit(end.ToString());break;}if(input[at++]!=',')Fail();Emit(",");}return;}if(c=='"'){Emit(String());return;}int start=at;while(at<input.Length&&" \t\r\n,]}".IndexOf(input[at])<0)at++;string atom=input.Substring(start,at-start);if(atom!="true"&&atom!="false"&&atom!="null"&&!Regex.IsMatch(atom,@"\A-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?\z"))Fail();Emit(atom);}
 }
 internal static class CodeValidation {
  internal static string Check(string path,string text){string ext=System.IO.Path.GetExtension(path??"").ToLowerInvariant();try{if(ext==".json"||ext==".lng")JsonTextFormatter.Format(text);else if(ext==".yaml"||ext==".yml"){var parser=new YamlDotNet.Core.Parser(new StringReader(text));int count=0;while(parser.MoveNext()){if(++count>500000)throw new FormatException(L.Text("codeEditor.large"));}}else if(ext==".xml"||ext==".xaml"){using(var reader=System.Xml.XmlReader.Create(new StringReader(text),new System.Xml.XmlReaderSettings{DtdProcessing=System.Xml.DtdProcessing.Prohibit,XmlResolver=null})){while(reader.Read()){}}}else return L.Text("codeEditor.noValidator");return L.Text("codeEditor.valid");}catch(Exception ex){return ex.Message;}}
 }
